-- The language layer and concept references (PRODUCT_BRIEF section 6, layers 2 and 3), generated by the
-- research agent and cached for every project that shares the concept.

alter table run drop constraint if exists run_kind_check;
alter table run add constraint run_kind_check check (kind in ('grade', 'mentor', 'language', 'references'));

-- Structured notes per concept and language (and framework, '' for none). language_note keeps a plain-text
-- copy so anything reading the shared table still works. Also the single-flight marker: a 'running' row
-- means another run is generating it. language '@references' marks reference searches for a concept.
create table if not exists concept_language (
  concept_id uuid not null references concept (id) on delete cascade,
  language   text not null,
  framework  text not null default '',
  status     text not null check (status in ('running', 'done', 'failed')),
  data       jsonb,
  model      text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (concept_id, language, framework)
);
